def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    danger_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    danger_bids.append(float(bid))

    if not alive:
        base = 8.0 if hp > 3 else 20.0
        return max(0.0, min(float(budget), base))

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units < 1.35:
        scarcity = 2
    elif units < 1.7:
        scarcity = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    danger_prev = max(danger_bids) if danger_bids else highest_prev

    urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if critical:
        target = max(72.0, danger_prev + 3.0)
        if scarcity == 2:
            target = max(target, highest_prev + 5.0)
        return max(0.0, min(float(budget), target))

    if urgent:
        target = max(55.0, danger_prev + 2.0)
        if scarcity >= 1:
            target = max(target, highest_prev + 3.0)
        return max(0.0, min(float(budget), target))

    if scarcity == 2:
        if highest_prev >= 110.0:
            target = 44.0
        elif highest_prev >= 80.0:
            target = highest_prev + 2.5
        else:
            target = max(58.0, highest_prev + 3.0)
    elif scarcity == 1:
        if highest_prev >= 120.0:
            target = 32.0
        elif highest_prev >= 90.0:
            target = 48.0
        else:
            target = max(42.0, highest_prev + 1.5)
    else:
        if highest_prev >= 100.0:
            target = 18.0
        elif highest_prev >= 70.0:
            target = 28.0
        else:
            target = 36.0

    if day >= 8 and hp > 4:
        target *= 0.92

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 12.0
    bid = min(float(budget), target)
    if budget - bid < reserve_floor:
        bid = max(0.0, float(budget) - reserve_floor)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.1)

    if day_context['supply'] < 18:
        return min(my_status['budget'], avg_prev * 1.2)

    return min(my_status['budget'], max(40.0, avg_prev * 0.9))
